import {createMusicSignal} from './music-signal.js?v=20261007-mobile3';
const buttons=[...document.querySelectorAll('[data-role]')];
function filter(role){if(!['all','production','writing','artist'].includes(role))role='all';let count=0;document.querySelectorAll('.release-card').forEach(card=>{card.hidden=role!=='all'&&!card.dataset.categories.split(' ').includes(role);if(!card.hidden)count++});buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.role===role)));document.querySelector('#result-count').textContent=`${count} RELEASES`;const url=new URL(location.href);role==='all'?url.searchParams.delete('role'):url.searchParams.set('role',role);history.replaceState(null,'',url)}
if(buttons.length){buttons.forEach(b=>b.addEventListener('click',()=>filter(b.dataset.role)));document.querySelectorAll('[data-role-link]').forEach(a=>a.addEventListener('click',()=>filter(a.dataset.roleLink)));filter(new URL(location.href).searchParams.get('role')||'all')}
const audio=document.querySelector('#file-audio');
if(audio){const signal=createMusicSignal(audio),button=document.querySelector('.listen-button'),canvas=document.querySelector('.audio-scope'),ctx=canvas.getContext('2d'),note=document.querySelector('.audio-note'),originalNote=note.textContent,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 button.addEventListener('click',async()=>{if(audio.paused){await signal.arm();try{await audio.play()}catch{note.textContent='Use the player below to start the record.'}}else audio.pause()});
 audio.addEventListener('play',()=>{button.textContent='PAUSE RECORD';button.setAttribute('aria-label','Pause record');note.textContent=originalNote});audio.addEventListener('pause',()=>{button.textContent='PLAY RECORD';button.setAttribute('aria-label','Play record')});audio.addEventListener('error',()=>note.textContent='Preview unavailable. Use the official release link below.');document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.pause()});
 function draw(){requestAnimationFrame(draw);if(document.hidden)return;ctx.clearRect(0,0,240,64);const s=signal.read();canvas.dataset.level=String(Math.round(s.level*1000));ctx.lineWidth=1.15;for(let j=0;j<3;j++){ctx.strokeStyle=['#91354b','#f0b8bc','#ba596e'][j];ctx.beginPath();for(let k=0;k<160;k++){const x=k/159*240,y=32+(s.playing&&!reduced?s.samples[(k*3+j*13)%512]*24:0)+(j-1)*3;k?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}}draw();
}
